        sse_encode_i_32(7, serializer);
        sse_encode_String(msg, serializer);
      case SdkError_InvalidUrl(msg: final msg):
        sse_encode_i_32(8, serializer);
        sse_encode_String(msg, serializer);
      case SdkError_Db(msg: final msg):
        sse_encode_i_32(9, serializer);
        sse_encode_String(msg, serializer);
      case SdkError_NoAccount(msg: final msg):
        sse_encode_i_32(10, serializer);
        sse_encode_String(msg, serializer);
      case SdkError_Cancelled(msg: final msg):
        sse_encode_i_32(11, serializer);
        sse_encode_String(msg, serializer);
    }
  }

  @protected
  void sse_encode_u_16(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint16(self);
  }

  @protected
  void sse_encode_u_32(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint32(self);
  }

  @protected
  void sse_encode_u_8(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint8(self);
  }

  @protected
  void sse_encode_unit(void self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
  }

  @protected
  void sse_encode_upload_info(UploadInfo self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.id, serializer);
    sse_encode_String(self.account, serializer);
    sse_encode_String(self.source, serializer);
    sse_encode_String(self.dfsPath, serializer);
    sse_encode_String(self.name, serializer);
    sse_encode_opt_box_autoadd_i_64(self.size, serializer);
    sse_encode_i_64(self.uploaded, serializer);
    sse_encode_opt_String(self.md5, serializer);
    sse_encode_opt_String(self.thumb, serializer);
    sse_encode_upload_state(self.state, serializer);
    sse_encode_opt_String(self.error, serializer);
    sse_encode_i_64(self.createDate, serializer);
    sse_encode_opt_box_autoadd_i_64(self.finishDate, serializer);
  }

  @protected
  void sse_encode_upload_item(UploadItem self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.path, serializer);
    sse_encode_String(self.dfsPath, serializer);
    sse_encode_opt_String(self.md5, serializer);
    sse_encode_opt_String(self.contentType, serializer);
    sse_encode_opt_String(self.thumb, serializer);
    sse_encode_bool(self.skipIfExists, serializer);
  }

  @protected
  void sse_encode_upload_query(UploadQuery self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_opt_String(self.account, serializer);
    sse_encode_opt_box_autoadd_upload_state(self.state, serializer);
    sse_encode_i_64(self.offset, serializer);
    sse_encode_i_64(self.limit, serializer);
  }

  @protected
  void sse_encode_upload_state(UploadState self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.index, serializer);
  }

  @protected
  void sse_encode_usize(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }
}

